21	type handoffFlags struct {
22		checkpoint string
23		session    string
24		format     string
25		limit      int
26		noGraph    bool
27		ask        string
28	}
29	
30	const (
31		handoffFormatMarkdown = "md"
32		handoffFormatJSON     = "json"
33	)
34	
35	func newHandoffCmd() *cobra.Command {
36		f := &handoffFlags{format: handoffFormatMarkdown, limit: handoff.DefaultLimit}
37		cmd := &cobra.Command{
38			Use:   "handoff",
39			Short: "Build a cited handoff packet for the next session",
40			Long: "Build a handoff packet summarizing recent checkpoints: what the last sessions\n" +
41				"were trying to do, what is still open, what was already tried and failed, and\n" +
42				"where work stopped.\n\n" +
43				"Every line carries the checkpoint it came from, so each claim can be traced\n" +
44				"back to the session that produced it.\n\n" +
45				"The --json output is a stable, documented shape intended for other tools.",
46			RunE: func(cmd *cobra.Command, _ []string) error {
47				// --json is the conventional spelling across this CLI; --format is
48				// kept for symmetry with the other renderers. Either selects JSON.
49				if jsonFlag, err := cmd.Flags().GetBool("json"); err == nil && jsonFlag {
50					f.format = handoffFormatJSON
51				}
52				switch f.format {
53				case handoffFormatMarkdown, handoffFormatJSON:
54				default:
55					cmd.SilenceUsage = true
56					return fmt.Errorf("unknown format %q: want %q or %q", f.format, handoffFormatMarkdown, handoffFormatJSON)
57				}
58				return runHandoff(cmd.Context(), cmd.OutOrStdout(), f)
59			},
60		}
61		cmd.Flags().StringVar(&f.checkpoint, "checkpoint", "", "Start from this checkpoint id instead of the newest")
62		cmd.Flags().StringVar(&f.session, "session", "", "Only read checkpoints from this session id")
63		cmd.Flags().StringVar(&f.ask, "ask", "", "Search the team's history for prior work on this task")
64		cmd.Flags().StringVar(&f.format, "format", handoffFormatMarkdown, "Output format: md or json")
65		cmd.Flags().IntVar(&f.limit, "limit", handoff.DefaultLimit, "Maximum checkpoints to read")
66		cmd.Flags().BoolVar(&f.noGraph, "no-graph", false, "Skip the graph-derived blast-radius section")
67		cmd.Flags().Bool("json", false, "Shorthand for --format json")
68		return cmd
69	}
70	
71	func runHandoff(ctx context.Context, out io.Writer, f *handoffFlags) error {
72		repo, err := gitrepo.OpenCurrent(ctx)
73		if err != nil {
74			return fmt.Errorf("open repository: %w", err)
75		}
76		defer repo.Close()
77	
78		stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{
79			BlobFetcher: FetchBlobsByHash,
80			RefFetcher:  FetchCheckpointRef,
81			ReadRemotes: strategy.CheckpointReadRemotes(ctx),
82		})
83		if err != nil {
84			return fmt.Errorf("open checkpoint store: %w", err)
85		}
86	
87		in, err := handoff.Load(ctx, stores.Persistent, handoff.LoadOptions{
88			Repo:       handoffRepoName(ctx),
89			Head:       handoffHeadCheckpoint(ctx, repo),
90			Limit:      f.limit,
91			Checkpoint: f.checkpoint,
92			Session:    f.session,
93		})
94		if err != nil {
95			return fmt.Errorf("read checkpoints: %w", err)
96		}
97	
98		opts := handoff.BuildOptions{NoGraph: f.noGraph, Ask: f.ask}
99		if cfg, ok := handoff.VectorConfigFromEnv(); ok {
100			opts.Searcher = handoff.NewVectorSearcher(cfg)
101		}
102		packet := handoff.BuildWith(ctx, in, opts)
103	
104		if f.format == handoffFormatJSON {
105			if err := handoff.RenderJSON(out, packet); err != nil {
106				return fmt.Errorf("render packet: %w", err)
107			}
108			return nil
109		}
110		if err := handoff.RenderMarkdown(out, packet); err != nil {
111			return fmt.Errorf("render packet: %w", err)
112		}
113		return nil
114	}
115	
116	// handoffRepoName identifies the repo for the packet header.
117	//
118	// Resolved from the origin remote, falling back to the worktree's base name.
119	// Deliberately local-only: currentRepoRef would answer more precisely but calls
120	// the control plane, and a handoff must still build offline.
121	func handoffRepoName(ctx context.Context) string {
122		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
123		if err == nil && owner != "" && repo != "" {
124			if forge != "" {
125				return fmt.Sprintf("%s/%s/%s", forge, owner, repo)
126			}
127			return owner + "/" + repo
128		}
129		if root, err := paths.WorktreeRoot(ctx); err == nil {
130			return "local/" + filepath.Base(root)
131		}
132		return "local"
133	}
134	
135	// handoffHeadCheckpoint returns the checkpoint ID on HEAD's Entire-Checkpoint
136	// trailer, or "" when HEAD carries none. Absence is normal -- the working tree
137	// may simply be ahead of the last checkpointed commit -- so it is never an error.
138	func handoffHeadCheckpoint(_ context.Context, repo *git.Repository) string {
139		head, err := repo.Head()
140		if err != nil {
141			return ""
142		}
143		commit, err := repo.CommitObject(head.Hash())
144		if err != nil {
145			return ""
146		}
147		if cpID, ok := trailers.ParseCheckpoint(commit.Message); ok {
148			return cpID.String()
149		}
150		return ""
151	}
