22	type VectorSearcher interface {
23		Query(ctx context.Context, text string, numResults int) ([]PriorHit, error)
24	}
25	
26	type PriorHit struct {
27		RepoKey      string
28		CheckpointID string
29		SessionID    int
30		SectionName  string
