42	func VectorConfigFromEnv() (VectorConfig, bool) {
43		c := VectorConfig{
44			Host:  strings.TrimSpace(os.Getenv("DATABRICKS_HOST")),
45			Token: strings.TrimSpace(os.Getenv("DATABRICKS_TOKEN")),
46			Index: strings.TrimSpace(os.Getenv("DATABRICKS_VECTOR_INDEX")),
47		}
48		if c.Host == "" || c.Token == "" || c.Index == "" {
49			return c, false
50		}
51		if !strings.HasPrefix(c.Host, "https://") {
52			return c, false
53		}
54		return c, true
55	}
