57	type restVectorSearcher struct {
58		cfg    VectorConfig
59		client *http.Client
60	}
61	
62	func NewVectorSearcher(cfg VectorConfig) VectorSearcher {
63		return &restVectorSearcher{cfg: cfg, client: &http.Client{Timeout: vectorQueryTimeout}}
64	}
65	
66	type vectorQueryRequest struct {
67		Columns     []string `json:"columns"`
68		QueryText   string   `json:"query_text"`
69		NumResults  int      `json:"num_results"`
70		FiltersJSON string   `json:"filters_json,omitempty"`
71	}
72	
73	type vectorQueryResponse struct {
74		Manifest struct {
75			Columns []struct {
76				Name string `json:"name"`
77			} `json:"columns"`
78		} `json:"manifest"`
79		Result struct {
80			DataArray [][]any `json:"data_array"`
81		} `json:"result"`
82	}
83	
84	var priorArtColumns = []string{
85		"repo_key", "checkpoint_id", "session_id", "section_name", "item_text", "cite_line",
86	}
87	
88	func (s *restVectorSearcher) Query(ctx context.Context, text string, numResults int) ([]PriorHit, error) {
89		body, err := json.Marshal(vectorQueryRequest{
90			Columns:     priorArtColumns,
91			QueryText:   text,
92			NumResults:  numResults,
93			FiltersJSON: `{"section_name": "dead_ends"}`,
94		})
95		if err != nil {
96			return nil, fmt.Errorf("encode vector query: %w", err)
97		}
98	
99		endpoint := fmt.Sprintf("%s/api/2.0/vector-search/indexes/%s/query",
100			strings.TrimSuffix(s.cfg.Host, "/"), s.cfg.Index)
101	
102		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
103		if err != nil {
104			return nil, fmt.Errorf("build vector query: %w", err)
105		}
106		req.Header.Set("Authorization", "Bearer "+s.cfg.Token)
107		req.Header.Set("Content-Type", "application/json")
108	
109		resp, err := s.client.Do(req)
110		if err != nil {
111			return nil, fmt.Errorf("vector query: %w", err)
112		}
113		defer resp.Body.Close()
114		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
115			return nil, fmt.Errorf("vector query: %s", resp.Status)
116		}
117	
118		var out vectorQueryResponse
119		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
120			return nil, fmt.Errorf("decode vector response: %w", err)
121		}
122		return hitsFrom(out), nil
123	}
124	
125	func hitsFrom(out vectorQueryResponse) []PriorHit {
126		idx := make(map[string]int, len(out.Manifest.Columns))
127		for i, c := range out.Manifest.Columns {
128			idx[c.Name] = i
129		}
130	
131		hits := make([]PriorHit, 0, len(out.Result.DataArray))
132		for _, row := range out.Result.DataArray {
133			get := func(name string) any {
134				i, ok := idx[name]
135				if !ok || i >= len(row) {
136					return nil
137				}
138				return row[i]
139			}
140			h := PriorHit{
141				RepoKey:      asString(get("repo_key")),
142				CheckpointID: asString(get("checkpoint_id")),
143				SessionID:    asInt(get("session_id")),
144				SectionName:  asString(get("section_name")),
145				ItemText:     asString(get("item_text")),
146				CiteLine:     asInt(get("cite_line")),
147			}
148			if h.ItemText == "" || h.CheckpointID == "" {
149				continue
150			}
151			hits = append(hits, h)
152		}
153		return hits
154	}
155	
156	func asString(v any) string {
157		s, ok := v.(string)
158		if !ok {
159			return ""
160		}
161		return strings.TrimSpace(s)
162	}
163	
164	func asInt(v any) int {
165		switch n := v.(type) {
166		case float64:
167			return int(n)
168		case string:
169			var out int
170			if _, err := fmt.Sscanf(n, "%d", &out); err == nil {
171				return out
172			}
173		}
174		return 0
175	}
