177	type globalMemoryExtractor struct {
178		searcher VectorSearcher
179		ask      string
180	}
181	
182	func newGlobalMemoryExtractor(s VectorSearcher, ask string) Extractor {
183		return globalMemoryExtractor{searcher: s, ask: ask}
184	}
185	
186	func (globalMemoryExtractor) Name() string { return SectionGlobalMemory }
187	
188	func (g globalMemoryExtractor) Extract(ctx context.Context, in Input) (Section, error) {
189		if g.searcher == nil {
190			return section(SectionGlobalMemory, nil, "vector search not configured"), nil
191		}
192	
193		query := strings.TrimSpace(g.ask)
194		if query == "" {
195			query = queryTextFrom(in)
196		}
197		if query == "" {
198			return section(SectionGlobalMemory, nil, "nothing to search on: no intent in range and no --ask given"), nil
199		}
200	
201		hits, err := g.searcher.Query(ctx, truncate(query, maxQueryTextChars), vectorNumResults)
202		if err != nil {
203			return section(SectionGlobalMemory, nil, fmt.Sprintf("vector search unavailable: %v", err)), nil
204		}
205		if len(hits) == 0 {
206			return section(SectionGlobalMemory, nil, "no prior work found for this task"), nil
207		}
208	
209		items := make([]Item, 0, len(hits))
210		for _, h := range hits {
211			items = append(items, Item{
212				Text: describeHit(h, in.Repo),
213				Cites: []Citation{{
214					CheckpointID: h.CheckpointID,
215					SessionIndex: h.SessionID,
216					Line:         h.CiteLine,
217				}},
218			})
219		}
220		return Section{
221			Name:  SectionGlobalMemory,
222			Items: items,
223			Note:  "retrieved by similarity across the team's history; verify before relying on it",
224		}, nil
225	}
226	
227	func describeHit(h PriorHit, currentRepo string) string {
228		if h.RepoKey != "" && h.RepoKey != currentRepo {
229			return fmt.Sprintf("[%s] %s", h.RepoKey, h.ItemText)
230		}
231		return h.ItemText
232	}
233	
234	func queryTextFrom(in Input) string {
235		var parts []string
236		for _, cp := range in.Checkpoints {
237			if cp.Summary == nil {
238				continue
239			}
240			if s := strings.TrimSpace(cp.Summary.Intent); s != "" {
241				parts = append(parts, s)
242			}
243			if len(parts) >= 2 {
244				break
245			}
246		}
247		return strings.Join(parts, " ")
248	}
