1	package handoff
2	
3	import (
4		"context"
5		"fmt"
6		"time"
7	)
8	
9	// Now is swappable so tests get a deterministic GeneratedAt.
10	var Now = time.Now
11	
12	// Build runs every extractor and assembles the packet.
13	//
14	// One extractor failing never fails the packet: its section is rendered with an
15	// "(unavailable: ...)" note and the rest still print. An agent that gets four
16	// good sections is oriented; one that gets an error message is not.
17	func Build(ctx context.Context, in Input, noGraph bool) Packet {
18		return BuildWith(ctx, in, BuildOptions{NoGraph: noGraph})
19	}
20	
21	func BuildWith(ctx context.Context, in Input, opts BuildOptions) Packet {
22		p := Packet{
23			Repo:        in.Repo,
24			GeneratedAt: Now().UTC(),
25			Head:        in.Head,
26		}
27		for _, x := range allExtractors(opts) {
28			sec, err := x.Extract(ctx, in)
29			if err != nil {
30				sec = Section{Name: x.Name(), Note: fmt.Sprintf("unavailable: %v", err)}
31			}
32			if sec.Name == "" {
33				sec.Name = x.Name()
34			}
35			p.Sections = append(p.Sections, sec)
36		}
37		return p
38	}
