19	// RenderMarkdown writes the packet as markdown.
20	//
21	// No TTY dependence: no pager, no colour, no width probing. The output is
22	// identical piped and interactive, because the primary reader is an agent that
23	// has no terminal.
24	func RenderMarkdown(w io.Writer, p Packet) error {
25		b := &strings.Builder{}
26	
27		fmt.Fprintf(b, "# Handoff — %s\n\n", p.Repo)
28		fmt.Fprintf(b, "Generated %s", p.GeneratedAt.Format("2006-01-02 15:04 MST"))
29		if p.Head != "" {
30			fmt.Fprintf(b, " · HEAD checkpoint `%s`", p.Head)
31		}
32		b.WriteString("\n")
33	
34		for _, sec := range p.Sections {
35			title := sectionTitles[sec.Name]
36			if title == "" {
37				title = sec.Name
38			}
39			fmt.Fprintf(b, "\n## %s\n\n", title)
40	
41			if len(sec.Items) == 0 {
42				note := sec.Note
43				if note == "" {
44					note = "nothing recorded"
45				}
46				fmt.Fprintf(b, "_%s_\n", note)
47				continue
48			}
49			for _, item := range sec.Items {
50				fmt.Fprintf(b, "- %s %s\n", item.Text, formatCites(item.Cites))
51			}
52			if sec.Note != "" {
53				fmt.Fprintf(b, "\n_%s_\n", sec.Note)
54			}
55		}
56	
57		if _, err := io.WriteString(w, b.String()); err != nil {
58			return fmt.Errorf("write handoff markdown: %w", err)
59		}
60		return nil
61	}
