63	// formatCites renders the provenance suffix. Every item has at least one
64	// citation by contract, so this is never empty in practice -- but it degrades
65	// quietly rather than panicking if that ever stops being true.
66	func formatCites(cites []Citation) string {
67		if len(cites) == 0 {
68			return ""
69		}
70		parts := make([]string, 0, len(cites))
71		for _, c := range cites {
72			s := shortID(c.CheckpointID)
73			if c.Line > 0 {
74				s = fmt.Sprintf("%s:%d", s, c.Line)
75			}
76			parts = append(parts, s)
77		}
78		return "`[" + strings.Join(parts, " ") + "]`"
79	}
80	
81	// shortID trims a checkpoint ID for display. The full ID stays in the JSON
82	// packet, which is what any tool follows up with.
83	func shortID(id string) string {
84		const n = 8
85		if len(id) <= n {
86			return id
87		}
88		return id[:n]
89	}
