9	// RenderJSON writes the machine-readable packet.
10	//
11	// This encoding is a published interface: it is what a fresh agent reads to
12	// bootstrap and what the Databricks ingest lane consumes on stdin. Adding a
13	// field is safe; renaming or removing one is a breaking change for both.
14	//
15	// Sections is normalised to a non-nil slice and every Section's Items to a
16	// non-nil array, so consumers can iterate without a null check -- a null where
17	// an array was expected is the classic way a downstream parser dies on the one
18	// packet that happened to have an empty section.
19	func RenderJSON(w io.Writer, p Packet) error {
20		if p.Sections == nil {
21			p.Sections = []Section{}
22		}
23		for i := range p.Sections {
24			if p.Sections[i].Items == nil {
25				p.Sections[i].Items = []Item{}
26			}
27		}
28		enc := json.NewEncoder(w)
29		enc.SetIndent("", "  ")
30		if err := enc.Encode(p); err != nil {
31			return fmt.Errorf("encode packet: %w", err)
32		}
33		return nil
34	}
