15	// Extract describes where the most recent session left off.
16	//
17	// Unlike the other sections this one reads the newest checkpoint only: it is a
18	// position report, not a history. It deliberately draws on metadata rather than
19	// the summary, so it still says something useful when no summary was generated
20	// -- which is the common case for a session that was interrupted, and exactly
21	// when a handoff matters most.
22	func (stoppedExtractor) Extract(_ context.Context, in Input) (Section, error) {
23		if len(in.Checkpoints) == 0 {
24			return section(SectionStopped, nil, in.emptyRangeNote()), nil
25		}
26		cp := in.Checkpoints[0]
27		cites := cite(cp)
28	
29		var items []Item
30		add := func(format string, args ...any) {
31			items = append(items, Item{Text: fmt.Sprintf(format, args...), Cites: cites})
32		}
33	
34		if cp.Summary != nil {
35			if outcome := strings.TrimSpace(cp.Summary.Outcome); outcome != "" {
36				add("%s", outcome)
37			}
38		}
39	
40		if in.Head != "" {
41			add("HEAD is at checkpoint %s", in.Head)
42		}
43	
44		if md := cp.Metadata; md != nil {
45			if len(md.FilesTouched) > 0 {
46				add("Last touched: %s", strings.Join(limit(md.FilesTouched, 8), ", "))
47			}
48			if a := md.Attribution; a != nil && a.TotalLinesChanged > 0 {
49				add("Attribution: %.0f%% agent across %d changed lines",
50					a.AgentPercentage, a.TotalLinesChanged)
51			}
52			if m := md.SessionMetrics; m != nil && m.TurnCount > 0 {
53				add("Session ran %d turns", m.TurnCount)
54			}
55			if t := md.TokenUsage; t != nil && t.OutputTokens > 0 {
56				add("Tokens: %d in / %d out", t.InputTokens, t.OutputTokens)
57			}
58		}
59	
60		return section(SectionStopped, items, "no position data on the latest checkpoint"), nil
61	}
