65	func limit(xs []string, n int) []string {
66		if len(xs) <= n {
67			return xs
68		}
69		out := make([]string, 0, n+1)
70		out = append(out, xs[:n]...)
71		return append(out, fmt.Sprintf("… +%d more", len(xs)-n))
72	}
