1	package handoff
2	
3	import (
4		"fmt"
5		"io"
6		"strings"
7	)
8	
9	// sectionTitles are the human headings. The machine-readable names in the JSON
10	// packet stay stable regardless of what we call them here.
11	var sectionTitles = map[string]string{
12		SectionIntent:    "What we were trying to do",
13		SectionOpenItems: "Still open",
14		SectionDeadEnds:  "Already tried — don't repeat",
15		SectionSurface:   "Blast radius",
16		SectionStopped:   "Where it stopped",
17	}
18	
19	// RenderMarkdown writes the packet as markdown.
20	//
21	// No TTY dependence: no pager, no colour, no width probing. The output is
22	// identical piped and interactive, because the primary reader is an agent that
23	// has no terminal.
24	func RenderMarkdown(w io.Writer, p Packet) error {
25		b := &strings.Builder{}
26	
27		fmt.Fprintf(b, "# Handoff — %s\n\n", p.Repo)
28		fmt.Fprintf(b, "Generated %s", p.GeneratedAt.Format("2006-01-02 15:04 MST"))
29		if p.Head != "" {
30			fmt.Fprintf(b, " · HEAD checkpoint `%s`", p.Head)
31		}
32		b.WriteString("\n")
33	
34		if packetHasIncompleteSection(p) {
35			b.WriteString("\n> **⚠ Incomplete context.** Some checkpoints in range were " +
36				"unreadable, missing, or had redacted fields. Sections marked " +
37				"**(incomplete)** below may not be the whole picture — verify before " +
38				"treating them as authoritative.\n")
39		}
40	
41		for _, sec := range p.Sections {
42			title := sectionTitles[sec.Name]
43			if title == "" {
44				title = sec.Name
45			}
46			if sec.Incomplete {
47				title += " (incomplete)"
48			}
49			fmt.Fprintf(b, "\n## %s\n\n", title)
50	
51			if len(sec.Items) == 0 {
52				note := sec.Note
53				if note == "" {
54					note = "nothing recorded"
55				}
56				fmt.Fprintf(b, "_%s_\n", note)
57				continue
58			}
59			for _, item := range sec.Items {
60				fmt.Fprintf(b, "- %s %s\n", item.Text, formatCites(item.Cites))
61			}
62			if sec.Note != "" {
63				fmt.Fprintf(b, "\n_%s_\n", sec.Note)
64			}
65		}
66	
67		if _, err := io.WriteString(w, b.String()); err != nil {
68			return fmt.Errorf("write handoff markdown: %w", err)
69		}
70		return nil
71	}
72	
73	// packetHasIncompleteSection reports whether any section in the packet was
74	// built from a gap-containing range. See Section.Incomplete.
75	func packetHasIncompleteSection(p Packet) bool {
76		for _, sec := range p.Sections {
77			if sec.Incomplete {
78				return true
79			}
80		}
81		return false
82	}
83	
84	// formatCites renders the provenance suffix. Every item has at least one
85	// citation by contract, so this is never empty in practice -- but it degrades
86	// quietly rather than panicking if that ever stops being true.
87	func formatCites(cites []Citation) string {
88		if len(cites) == 0 {
89			return ""
90		}
91		parts := make([]string, 0, len(cites))
92		for _, c := range cites {
93			s := shortID(c.CheckpointID)
94			if c.Line > 0 {
95				s = fmt.Sprintf("%s:%d", s, c.Line)
96			}
97			parts = append(parts, s)
98		}
99		return "`[" + strings.Join(parts, " ") + "]`"
100	}
101	
102	// shortID trims a checkpoint ID for display. The full ID stays in the JSON
103	// packet, which is what any tool follows up with.
104	func shortID(id string) string {
105		const n = 8
106		if len(id) <= n {
107			return id
108		}
109		return id[:n]
110	}
