1	package handoff
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"net/http"
9		"os"
10		"strings"
11		"time"
12	
13		"github.com/entireio/cli/redact"
14	)
15	
16	const (
17		SectionGlobalMemory = "prior_art"
18	
19		vectorQueryTimeout = 20 * time.Second
20		vectorNumResults   = 5
21		maxQueryTextChars  = 400
22	)
23	
24	type VectorSearcher interface {
25		Query(ctx context.Context, text string, numResults int) ([]PriorHit, error)
26	}
27	
28	type PriorHit struct {
29		RepoKey      string
30		CheckpointID string
31		SessionID    int
32		SectionName  string
33		ItemText     string
34		CiteLine     int
35		Score        float64
36	}
37	
38	type VectorConfig struct {
39		Host  string
40		Token string
41		Index string
42	}
43	
44	func VectorConfigFromEnv() (VectorConfig, bool) {
45		c := VectorConfig{
46			Host:  strings.TrimSpace(os.Getenv("DATABRICKS_HOST")),
47			Token: strings.TrimSpace(os.Getenv("DATABRICKS_TOKEN")),
48			Index: strings.TrimSpace(os.Getenv("DATABRICKS_VECTOR_INDEX")),
49		}
50		if c.Host == "" || c.Token == "" || c.Index == "" {
51			return c, false
52		}
53		if !strings.HasPrefix(c.Host, "https://") {
54			return c, false
55		}
56		return c, true
57	}
58	
59	type restVectorSearcher struct {
60		cfg    VectorConfig
61		client *http.Client
62	}
63	
64	func NewVectorSearcher(cfg VectorConfig) VectorSearcher {
65		return &restVectorSearcher{cfg: cfg, client: &http.Client{Timeout: vectorQueryTimeout}}
66	}
67	
68	type vectorQueryRequest struct {
69		Columns     []string `json:"columns"`
70		QueryText   string   `json:"query_text"`
71		NumResults  int      `json:"num_results"`
72		FiltersJSON string   `json:"filters_json,omitempty"`
73	}
74	
75	type vectorQueryResponse struct {
76		Manifest struct {
77			Columns []struct {
78				Name string `json:"name"`
79			} `json:"columns"`
80		} `json:"manifest"`
81		Result struct {
82			DataArray [][]any `json:"data_array"`
83		} `json:"result"`
84	}
85	
86	var priorArtColumns = []string{
87		"repo_key", "checkpoint_id", "session_id", "section_name", "item_text", "cite_line",
88	}
89	
90	func (s *restVectorSearcher) Query(ctx context.Context, text string, numResults int) ([]PriorHit, error) {
91		body, err := json.Marshal(vectorQueryRequest{
92			Columns:     priorArtColumns,
93			QueryText:   text,
94			NumResults:  numResults,
95			FiltersJSON: `{"section_name": "dead_ends"}`,
96		})
97		if err != nil {
98			return nil, fmt.Errorf("encode vector query: %w", err)
99		}
100	
101		endpoint := fmt.Sprintf("%s/api/2.0/vector-search/indexes/%s/query",
102			strings.TrimSuffix(s.cfg.Host, "/"), s.cfg.Index)
103	
104		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
105		if err != nil {
106			return nil, fmt.Errorf("build vector query: %w", err)
107		}
108		req.Header.Set("Authorization", "Bearer "+s.cfg.Token)
109		req.Header.Set("Content-Type", "application/json")
110	
111		resp, err := s.client.Do(req)
112		if err != nil {
113			return nil, fmt.Errorf("vector query: %w", err)
114		}
115		defer resp.Body.Close()
116		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
117			return nil, fmt.Errorf("vector query: %s", resp.Status)
118		}
119	
120		var out vectorQueryResponse
121		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
122			return nil, fmt.Errorf("decode vector response: %w", err)
123		}
124		return hitsFrom(out), nil
125	}
126	
127	func hitsFrom(out vectorQueryResponse) []PriorHit {
128		idx := make(map[string]int, len(out.Manifest.Columns))
129		for i, c := range out.Manifest.Columns {
130			idx[c.Name] = i
131		}
132	
133		hits := make([]PriorHit, 0, len(out.Result.DataArray))
134		for _, row := range out.Result.DataArray {
135			get := func(name string) any {
136				i, ok := idx[name]
137				if !ok || i >= len(row) {
138					return nil
139				}
140				return row[i]
141			}
142			h := PriorHit{
143				RepoKey:      asString(get("repo_key")),
144				CheckpointID: asString(get("checkpoint_id")),
145				SessionID:    asInt(get("session_id")),
146				SectionName:  asString(get("section_name")),
147				ItemText:     asString(get("item_text")),
148				CiteLine:     asInt(get("cite_line")),
149			}
150			if h.ItemText == "" || h.CheckpointID == "" {
151				continue
152			}
153			hits = append(hits, h)
154		}
155		return hits
156	}
157	
158	func asString(v any) string {
159		s, ok := v.(string)
160		if !ok {
161			return ""
162		}
163		return strings.TrimSpace(s)
164	}
165	
166	func asInt(v any) int {
167		switch n := v.(type) {
168		case float64:
169			return int(n)
170		case string:
171			var out int
172			if _, err := fmt.Sscanf(n, "%d", &out); err == nil {
173				return out
174			}
175		}
176		return 0
177	}
178	
179	type globalMemoryExtractor struct {
180		searcher VectorSearcher
181		ask      string
182	}
183	
184	func newGlobalMemoryExtractor(s VectorSearcher, ask string) Extractor {
185		return globalMemoryExtractor{searcher: s, ask: ask}
186	}
187	
188	func (globalMemoryExtractor) Name() string { return SectionGlobalMemory }
189	
190	func (g globalMemoryExtractor) Extract(ctx context.Context, in Input) (Section, error) {
191		if g.searcher == nil {
192			return section(SectionGlobalMemory, nil, "vector search not configured"), nil
193		}
194	
195		query := strings.TrimSpace(g.ask)
196		if query == "" {
197			query = queryTextFrom(in)
198		}
199		if query == "" {
200			return section(SectionGlobalMemory, nil, "nothing to search on: no intent in range and no --ask given"), nil
201		}
202	
203		// Privacy Boundary: query text originates from either --ask (typed
204		// verbatim by the user) or a checkpoint's Summary.Intent -- both are
205		// prompt-shaped text. Neither has been through the checkpoint storage
206		// redaction pipeline by this point, and this is the one place in the
207		// package that leaves the process over the network, to a service Entire
208		// does not control. Redact before it is ever placed in an HTTP request
209		// body, using only the local, non-network scanners (redact.String makes
210		// no outbound call itself).
211		query = redact.String(query)
212	
213		hits, err := g.searcher.Query(ctx, truncate(query, maxQueryTextChars), vectorNumResults)
214		if err != nil {
215			return section(SectionGlobalMemory, nil, fmt.Sprintf("vector search unavailable: %v", err)), nil
216		}
217		if len(hits) == 0 {
218			return section(SectionGlobalMemory, nil, "no prior work found for this task"), nil
219		}
220	
221		items := make([]Item, 0, len(hits))
222		for _, h := range hits {
223			items = append(items, Item{
224				Text: describeHit(h, in.Repo),
225				Cites: []Citation{{
226					CheckpointID: h.CheckpointID,
227					SessionIndex: h.SessionID,
228					Line:         h.CiteLine,
229				}},
230			})
231		}
232		return Section{
233			Name:  SectionGlobalMemory,
234			Items: items,
235			Note:  "retrieved by similarity across the team's history; verify before relying on it",
236		}, nil
237	}
238	
239	func describeHit(h PriorHit, currentRepo string) string {
240		if h.RepoKey != "" && h.RepoKey != currentRepo {
241			return fmt.Sprintf("[%s] %s", h.RepoKey, h.ItemText)
242		}
243		return h.ItemText
244	}
245	
246	func queryTextFrom(in Input) string {
247		var parts []string
248		for _, cp := range in.Checkpoints {
249			if cp.Summary == nil {
250				continue
251			}
252			if s := strings.TrimSpace(cp.Summary.Intent); s != "" {
253				parts = append(parts, s)
254			}
255			if len(parts) >= 2 {
256				break
257			}
258		}
259		return strings.Join(parts, " ")
260	}
